return ['domain'=>'transparai','plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'es_ES','project-id-version'=>'TransparAI','pot-creation-date'=>'2026-09-08','po-revision-date'=>'2026-09-08','messages'=>['Detect AI images from C2PA Content Credentials and IPTC metadata, label them with a visible AI badge and a machine-readable EU AI Act disclosure.'=>'Detecta imágenes de IA a partir de las Content Credentials de C2PA y los metadatos IPTC, las señala con una insignia visible y una declaración legible por máquina para el Reglamento europeo de IA.','This content is AI-generated'=>'Este contenido está generado por IA','Shows a short note ahead of the content. The wording can be changed in the TransparAI settings.'=>'Muestra un aviso breve delante del contenido. El texto se cambia en los ajustes de TransparAI.','Media is AI-generated'=>'El medio está generado por IA','The file metadata could not be updated (file not writable). The label state in WordPress and the metadata inside the file may differ.'=>'No se han podido actualizar los metadatos del archivo (archivo sin permiso de escritura). El estado de la etiqueta en WordPress y los metadatos dentro del archivo pueden diferir.','Confirm AI label'=>'Confirmar la etiqueta de IA','Not AI, dismiss'=>'No es IA, descartar','Re-check file metadata'=>'Volver a comprobar los metadatos del archivo','Check delivery'=>'Comprobar la entrega','Show file metadata'=>'Mostrar los metadatos del archivo','AI content'=>'Contenido de IA','Controls the front-end badge, the machine-readable file metadata and the media library filter.'=>'Controla la insignia pública, los metadatos escritos en el archivo y el filtro de la biblioteca de medios.','Default (site setting)'=>'Predeterminado (ajuste del sitio)','Top left'=>'Arriba a la izquierda','Top right'=>'Arriba a la derecha','Bottom left'=>'Abajo a la izquierda','Bottom right'=>'Abajo a la derecha','Caption line below the image'=>'Línea de pie debajo de la imagen','Hide the visible badge on this image'=>'Ocultar la insignia visible en esta imagen','Badge position'=>'Posición de la insignia','Overrides this image only. Use it if a theme overlay covers the badge here.'=>'Se aplica solo a esta imagen. Úsalo cuando una capa del tema tape la insignia aquí.','AI generator'=>'Generador de IA','Name of the AI tool, e.g. "Midjourney". Shown by the badge source option and the {generator} placeholder.'=>'Nombre de la herramienta de IA, por ejemplo «Midjourney». Lo muestra la opción de origen de la insignia y el marcador {generator}.','certain'=>'seguro','likely'=>'probable','hint'=>'indicio','You are not allowed to do that.'=>'No tienes permiso para hacer eso.','Unknown action.'=>'Acción desconocida.','Invalid attachment.'=>'Adjunto no válido.','Files'=>'Archivos','format cannot carry the declaration'=>'el formato no puede llevar la declaración','declaration present'=>'declaración presente','declaration missing'=>'declaración ausente','No readable file found for this attachment.'=>'No se ha encontrado ningún archivo legible para este adjunto.','Digital source type in the main file'=>'Digital source type en el archivo principal','None declared.'=>'Sin declaración.','Detection evidence'=>'Indicios de la detección','History'=>'Historial','system'=>'sistema','XMP packet of the main file'=>'Paquete XMP del archivo principal','This file carries no XMP block.'=>'Este archivo no contiene ningún bloque XMP.','AI status: all'=>'Estado de IA: todos','Only AI-labeled'=>'Solo los marcados como IA','Detected, needs review'=>'Detectado, pendiente de revisión','Without AI label'=>'Sin etiqueta de IA','Mark as AI-generated'=>'Marcar como generado por IA','Remove AI label'=>'Quitar la etiqueta de IA','Please select media first.'=>'Selecciona primero algún medio.','Updating the AI label failed.'=>'No se ha podido actualizar la etiqueta de IA.','Result'=>'Resultado','No AI provenance signals found in the file.'=>'No se han encontrado señales de procedencia de IA en el archivo.','The label was set, but the metadata could not be written into the file. Check the write permissions of the uploads directory.'=>'La etiqueta se ha guardado, pero los metadatos no se han podido escribir en el archivo. Revisa los permisos de escritura del directorio de subidas.','Hide file metadata'=>'%1$d comprobados: %2$d entregados con la declaración, %3$d sin ella.','%1$d checked: %2$d delivered with the declaration, %3$d without, %4$d not comparable.'=>'%1$d comprobados: %2$d entregados con la declaración, %3$d sin ella, %4$d no comparables.','Confirm detected AI label'=>'Descartar la etiqueta de IA detectada','Dismiss detected AI label'=>'Etiqueta de IA actualizada en %d archivo de medios.','AI label updated for %d media file.'=>'No tienes permiso para exportar esto.' . "\0" . 'No tienes permiso para exportar esto.','You are not allowed to export this.'=>'No se ha podido iniciar la exportación.','The export could not be started.'=>'Ajustes','Settings'=>'%1$d analizados, %2$d etiquetados automáticamente, %3$d pendientes de revisión, %4$d omitidos (ya decididos).','%1$d scanned, %2$d auto-labeled, %3$d queued for review, %4$d skipped (already decided).'=>'Análisis completado.','Scan complete.'=>'La petición de análisis ha fallado. Puedes reiniciarlo para continuar.','Scan request failed. You can restart to continue.'=>'Ajustes guardados.','Settings saved.'=>'Estado de la biblioteca','Library status'=>'Archivos de medios','Media files'=>'Etiquetados como IA','Labeled as AI'=>'Pendientes de revisión','Waiting for review'=>'Analizados','Scanned'=>'Abrir la cola de revisión','Open review queue'=>'Exportar la auditoría en CSV','Export audit CSV'=>'La exportación incluye cada archivo etiquetado o pendiente con su origen de detección, su nivel de confianza y el último cambio registrado.','The export lists every labeled and pending file with its detection source, confidence and the last recorded change.'=>'Analizar la biblioteca existente','Scan existing library'=>'Lee los metadatos de tus archivos de medios existentes (C2PA, XMP/IPTC, firmas de generadores) en lotes pequeños. Nada sale de tu servidor.','Reads the metadata of your existing media files (C2PA, XMP/IPTC, generator signatures) in small batches. Nothing leaves your server.'=>'Analizar los medios nuevos o sin analizar','Scan new/unscanned media'=>'Volver a analizar todo','Rescan everything'=>'Pausar','Pause'=>'Reparación automática, último ciclo completo: %1$d archivos etiquetados comprobados, %2$d reparados, %3$d fallidos (hace %4$s).','Auto-repair, last full sweep: %1$d labeled files checked, %2$d repaired, %3$d failed (%4$s ago).'=>'Insignia visible','Visible badge'=>'Mostrar la insignia','Show badge'=>'Mostrar una insignia visible en los medios etiquetados de la parte pública','Show a visible badge on labeled media in the front end'=>'Fecha de inicio','Start date'=>'Solo los medios subidos a partir de esta fecha reciben la insignia pública; los anteriores siguen etiquetados solo en la administración. Déjalo vacío para mostrar la insignia en todos los medios etiquetados.','Only media uploaded on or after this date get the front-end badge; earlier media stay labeled in the admin only. Leave empty to badge all labeled media.'=>'Texto de la insignia','Badge text'=>'Generado por IA','AI-generated'=>'Déjalo vacío para usar el texto traducido por defecto.','Leave empty for the translated default label.'=>'Marcadores: %1$s (generador detectado o introducido) y %2$s (título del sitio), por ejemplo %3$s. Las imágenes sin generador conocido usan el texto por defecto.','Placeholders: %1$s (detected or manually set generator) and %2$s (site title), e.g. %3$s. Images without a known generator fall back to the default label.'=>'Aspecto','Appearance'=>'Superpuesta a la imagen','Overlay on the image'=>'Oscura','Dark'=>'Clara','Light'=>'Contorno','Outline'=>'Solo icono (texto corto)','Icon only (short label)'=>'Pequeña','Small'=>'Mediana','Medium'=>'Grande','Large'=>'Extras','Extras'=>'Mostrar el generador detectado en la insignia (por ejemplo «Generado por IA · Midjourney»; se ignora si el texto de la insignia contiene {generator})','Show the detected generator in the badge (e.g. "AI-generated · Midjourney"; ignored when the badge text contains {generator})'=>'Añadir la etiqueta al texto alternativo de la imagen (lectores de pantalla)','Append the label to the image alt text (screen readers)'=>'Mover automáticamente la insignia a otra esquina, o debajo de la imagen, cuando una capa del tema la tape (recomendado, necesita JavaScript)','Automatically move a badge to another corner, or below the image, if a theme overlay covers it (recommended, needs JavaScript)'=>'Etiquetar también las imágenes mostradas sin ID de adjunto (campos ACF, carruseles, maquetadores) y los fondos CSS (experimental, necesita JavaScript)','Also label images printed without an attachment ID (ACF fields, sliders, builders) and CSS backgrounds (experimental, needs JavaScript)'=>'Aviso de página','Page notice'=>'Añadir un aviso breve al final de las páginas que contienen medios etiquetados','Add a short note at the end of pages that contain labeled media'=>'Esta página contiene medios generados por IA.','This page contains AI-generated media.'=>'Texto generado por IA','AI-generated text'=>'Aviso de contenido','Content note'=>'Este texto se ha creado con ayuda de IA.','This text was created with the help of AI.'=>'Se muestra delante de las entradas que marcas con la casilla «Este contenido está generado por IA» en la barra lateral del editor.','Shown ahead of posts you mark with the "This content is AI-generated" checkbox in the editor sidebar.'=>'Detección automática','Automatic detection'=>'Detectar al subir','Detect on upload'=>'Inspeccionar las subidas nuevas en busca de procedencia de IA (C2PA, XMP/IPTC, firmas de generadores)','Inspect new uploads for AI provenance (C2PA, XMP/IPTC, generator signatures)'=>'Declaraciones formales','Standard declarations'=>'Etiquetar automáticamente','Label automatically'=>'Poner en la cola de revisión','Put into review queue'=>'Ignorar','Ignore'=>'Archivos que declaran explícitamente un origen de IA (IPTC DigitalSourceType, declaración de IA en C2PA, declaración AIGC).','Files that explicitly declare AI origin (IPTC DigitalSourceType, AI claim in C2PA, AIGC declaration).'=>'Firmas de generadores','Generator signatures'=>'Señales fuertes sin declaración formal (parámetros de Stable Diffusion, flujos de ComfyUI, nombres de generadores en EXIF/XMP, C2PA escrito por una cámara).','Strong signals without a formal declaration (Stable Diffusion parameters, ComfyUI workflows, generator names in EXIF/XMP, camera-written C2PA).'=>'Más fuentes','More sources'=>'Analizar también las subidas de vídeo y audio (C2PA en MP4/MOV, declaraciones AIGC en MP3)','Also scan video and audio uploads (MP4/MOV C2PA, MP3 AIGC declarations)'=>'Usar los patrones del nombre de archivo como indicios para la revisión (nunca etiqueta automáticamente)','Use filename patterns as review hints (never labels automatically)'=>'Metadatos legibles por máquina en los archivos','Machine-readable file metadata'=>'Escribir en los archivos','Write into files'=>'Escribir el IPTC DigitalSourceType como XMP en los archivos JPEG, PNG, WebP y AVIF etiquetados (todos los tamaños generados)','Write the IPTC DigitalSourceType as XMP into labeled JPEG, PNG, WebP and AVIF files (all size variants)'=>'Reflejarlo también en IPTC-IIM (JPEG, solo cuando el archivo no tiene otro bloque IPTC)','Also mirror it into IPTC-IIM (JPEG, only when the file has no other IPTC block)'=>'Reparación automática','Auto-repair'=>'Restaurar los metadatos cuando los optimizadores de imágenes o la regeneración de tamaños los eliminan (ciclo de integridad cada hora)','Restore the metadata when image optimizers or regeneration strip it (hourly integrity sweep)'=>'Comprobación de la entrega','Delivery check'=>'Permitir comprobar si la declaración sobrevive a la entrega','Allow checking whether the declaration survives delivery'=>'Añade un botón aquí y en los detalles del adjunto. Al pulsarlo, el plugin descarga la imagen desde su propia URL pública y compara los bytes entregados con el archivo del disco, que es la única forma de notar que un CDN de optimización recodifica tus imágenes y elimina la declaración por el camino. La petición va a tu propio sitio y a ningún otro, y solo ocurre cuando pulsas el botón.','Adds a button to the attachment details and here. On click, the plugin fetches that image over its own public URL and compares the delivered bytes with the file on disk, which is the only way to notice that an optimizing CDN re-encodes your images and drops the declaration on the way out. The request goes to your own site and nowhere else, and it only ever happens when you press the button.'=>'Comprobar una muestra de cinco archivos','Check a sample of five files'=>'Datos estructurados','Structured data'=>'Añadir JSON-LD de Schema.org con el digital source type de IPTC para los medios etiquetados de cada página (los buscadores lo leen sin abrir los archivos)','Add Schema.org JSON-LD with the IPTC digital source type for the labeled media of each page (search engines read it without opening the files)'=>'Desinstalación','Uninstall'=>'Eliminación de datos','Data removal'=>'Borrar todos los datos del plugin (etiquetas, resultados de detección, ajustes) al desinstalarlo','Delete all plugin data (labels, detection results, settings) when the plugin is uninstalled'=>'Guardar los cambios','Save changes'=>'Enlaces de TransparAI','TransparAI links'=>'Foro de soporte','Support forum'=>'La comprobación de la entrega está desactivada.','The delivery check is switched off.'=>'Este adjunto no tiene ningún archivo.','This attachment has no file.'=>'El archivo se sirve desde otro host, así que no se comprueba.','The file is served from another host, so it is not checked.'=>'El archivo del disco no lleva ninguna declaración de IA, así que no hay nada que comparar.','The file on disk carries no AI declaration, so there is nothing to compare.'=>'No se ha podido descargar la imagen desde su URL pública.','The image could not be fetched over its public URL.'=>'La respuesta no era una imagen legible.','The response was not a readable image.'=>'La declaración está presente en el archivo entregado.','The declaration is present in the delivered file.'=>'El archivo entregado no lleva ninguna declaración. Algo entre WordPress y el visitante recodifica la imagen, normalmente un CDN de optimización o un proxy.','The delivered file carries no declaration. Something between WordPress and the visitor re-encodes the image, usually an optimizing CDN or a proxy.'=>'Entregado con la declaración intacta','Delivered with the declaration intact'=>'Entregado sin la declaración','Delivered without the declaration'=>'Nada que comprobar','Nothing to check'=>'Servido desde otro host','Served from another host'=>'No se ha podido descargar','Could not be fetched'=>'No se ha podido descargar']];